def lineare_suche(liste, ziel):
    for i in range(len(liste)):
        if liste[i] == ziel:
            return i
    return -1

namen = ["Lea", "Tom", "Ali", "Mia"]
print(lineare_suche(namen, "Ali"))  # 2
print(lineare_suche(namen, "Max"))  # -1

def binaere_suche(liste, ziel):
    links = 0
    rechts = len(liste) - 1
    while links <= rechts:
        mitte = (links + rechts) // 2
        if liste[mitte] == ziel:
            return mitte
        elif liste[mitte] < ziel:
            links = mitte + 1
        else:
            rechts = mitte - 1
    return -1

z = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]
print(binaere_suche(z, 23))  # 5
print(binaere_suche(z, 7))   # -1

